"""Build the three fictional-host landing pages from approved pilot content."""
from pathlib import Path
import datetime
import html
import json

ROOT = Path(__file__).resolve().parent.parent
VERSION = (ROOT / 'VERSION').read_text().strip()
HOSTS = [
 dict(slug='june.rowan', key='june', name='June Rowan', asset='june-rowan', niche='Everyday wellness', headline='A little outside.<br>A fresh start.', intro='Small outdoor habits. Easy restarts. Everyday wellness without the pressure.', tagline='One small step at a time.', title='Start again today', duration='24 seconds', video='june-rowan-01-captioned.mp4', handle='june.rowan.daily', reel='Dehvx22qvhP', blurb='Missed a day? Start with today’s walk. A few minutes, then decide whether you feel like going farther.', topics=[('Start small','A little walk is a place to begin. No elaborate routine required.'),('Try again','Yesterday can stay yesterday. Make room for a fresh start today.'),('Keep it everyday','Sneakers, a front door, and a few minutes outside.')], transcript="Missed yesterday? Today doesn’t need to be a punishment. If you planned a little walk and it never happened, take today’s walk. Start at the gate. Actually, start by finding your sneakers. Check under that chair. A few minutes, then decide whether you feel like going farther. Save this for your next restart."),
 dict(slug='nora.vela', key='nora', name='Nora Vela', asset='nora-vela', niche='Business experiments', headline='Count the costs.<br>Keep it honest.', intro='Tracking our business experiments: time, costs, fees and results.', tagline='The numbers behind the notification.', title='What’s left from the sale?', duration='28 seconds', video='nora-vela-01-captioned.mp4', handle='nora.vela.builds', reel='Dei8dzOSvA0', blurb='A $10 sale isn’t $10 in profit. A made-up example of the costs we need to count before calling something a win.', topics=[('Count the costs','Sale price, production, fees and software: put every number on the page.'),('Count the hours','The afternoon fixing a checkout belongs in the story, too.'),('Show the work','Document the experiments and share actual results when we have them.')], transcript="The sale price isn’t the profit. Imagine a ten-dollar sale. These are made-up numbers. Two dollars to make it. Another dollar in fees. Seven left. Wait, we haven’t counted the monthly software bill. Or the afternoon spent fixing the checkout. That ten-dollar notification is only the first number. Follow along. We’ll show the costs when we share our results."),
 dict(slug='elena.brooks', key='elena', name='Elena Brooks', asset='elena-brooks', niche='Everyday relationships', headline='A clearer text.<br>A warmer connection.', intro='Clearer texts. Warmer invitations. Boundaries without the essay.', tagline='Make the invitation happen.', title='“We should catch up” needs a date', duration='27 seconds', video='elena-brooks-01-captioned.mp4', handle='elena.brooks.notes', reel='Dei9MvqJMJI', blurb='A day and a time make an invitation easier to answer. Send this to the friend you’ve been meaning to see.', topics=[('Say it clearly','A simple invitation gives someone something they can answer.'),('Leave room','Offer an easy alternative when the first plan doesn’t work.'),('Keep it warm','Everyday connection, with a little less overthinking.')], transcript="We should catch up needs a date. Otherwise, you can both keep saying definitely until October becomes next October. Try: Want to grab coffee Saturday? I’m free around eleven. Actually, give them an easy alternative: If Saturday doesn’t work, what works for you? There. An invitation they can answer. Send this to the friend you’ve been meaning to see.")
]

def esc(value):
    """Escape approved plain-text content for an HTML context."""
    return html.escape(value, quote=True)


def settings():
    """Return the shared accessible display-settings interface."""
    return f'''<button class="gear" data-open-settings aria-label="Open display settings" aria-haspopup="dialog"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 3-1 2 2 3-1 1-3 3-1 1-3-2-2 1-3-3-2-3 1-2-2Z"/><circle cx="12" cy="12" r="3"/></svg></button>'''


def dialog():
    """Return settings with native focus trapping and Escape dismissal."""
    return f'''<dialog id="settings" aria-labelledby="settings-title"><div class="dialog-head"><strong id="settings-title">Display settings</strong><button data-close-settings aria-label="Close display settings">×</button></div><div class="setting"><span>About</span><span>v{VERSION}</span></div><div class="setting"><span>Theme</span><div class="theme-buttons"><button data-theme="day" aria-pressed="true">Day</button><button data-theme="night" aria-pressed="false">Night</button></div></div><label class="setting" for="alpha"><span>Transparency</span><input id="alpha" type="range" min="75" max="94" value="86"></label><label class="setting" for="blur"><span>Translucency</span><input id="blur" type="range" min="8" max="24" value="20"></label></dialog><span class="version">v{VERSION}</span><button class="back-top" aria-label="Back to top">↑</button><script src="assets/creators.js?v={VERSION}" defer></script>'''


def footer(name):
    """Keep AI identity and the scoped policy routes visible on every page."""
    return f'''<footer class="wrap"><div class="foot-top"><span>{esc(name)} · A fictional AI creator from Web By Elie</span><nav aria-label="Policies"><a href="creators.privacy">Privacy</a><a href="creators.terms">Terms</a><a href="creators.data-deletion">Data deletion</a></nav></div><p class="fiction">The person, image and voice are AI-generated. These videos share everyday ideas and documented experiments; they do not represent a real person’s lived experience.</p></footer>'''


def head(title, description, slug, image=None):
    """Build public metadata without presenting fictional hosts as real people."""
    url = 'https://web-by-elie.com/' + slug
    return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{url}">{f'<meta property="og:image" content="https://web-by-elie.com/assets/creators/{image}">' if image else ''}<meta name="twitter:card" content="summary_large_image"><link rel="icon" href="assets/web-by-elie-logo.svg"><link rel="stylesheet" href="assets/creators.css?v={VERSION}"></head>'''


for host in HOSTS:
    h = host
    insta = 'https://www.instagram.com/' + h['handle'] + '/'
    reel = insta + 'reel/' + h['reel'] + '/'
    cards = ''.join(f'<article class="note"><span class="number">0{i}</span><h3>{esc(title)}</h3><p>{esc(copy)}</p></article>' for i, (title, copy) in enumerate(h['topics'], 1))
    body = f'''<body data-host="{h['key']}"><header class="wrap bar"><a class="brand" href="{h['slug']}">{h['name']}</a><nav aria-label="Primary"><a class="nav-about" href="#approach">The little things</a><a href="#watch">Watch</a>{settings()}</nav></header><main><section class="wrap hero"><div class="hero-copy"><p class="eyebrow">{h['niche']}</p><h1>{h['headline']}</h1><p class="intro">{h['intro']}</p><div class="actions"><a class="button" href="{insta}">Follow on Instagram <span aria-hidden="true">↗</span></a><a class="text-link" href="#watch">Watch the first video</a></div><p class="disclosure">FICTIONAL AI CREATOR · AI-GENERATED IMAGE &amp; VOICE</p></div><figure class="portrait"><img src="assets/creators/{h['asset']}-profile.jpg" width="1024" height="1024" alt="AI-generated portrait of fictional creator {h['name']}" fetchpriority="high"><figcaption><b>{h['name']}</b><span>{h['niche']}</span></figcaption></figure></section><section class="wrap" id="approach" aria-label="What you’ll find"><div class="section-line"><span>{h['tagline']}</span><span>Everyday ideas</span></div><div class="notes">{cards}</div></section><section class="wrap video-section" id="watch"><div class="video-copy"><p class="eyebrow">The first video · {h['duration']}</p><h2>{esc(h['title'])}</h2><p>{esc(h['blurb'])}</p><a class="text-link" href="{reel}">Watch the Reel on Instagram ↗</a><details class="transcript"><summary>Read the transcript</summary><p>{esc(h['transcript'])}</p></details></div><div class="video-wrap"><video controls playsinline preload="none" poster="assets/creators/{h['asset']}-profile.jpg" aria-label="{esc(h['title'])}, featuring fictional AI creator {h['name']}"><source src="assets/creators/{h['video']}" type="video/mp4"><track src="assets/creators/{h['asset']}.vtt" kind="captions" srclang="en" label="English">Your browser does not support video. <a href="{reel}">Watch on Instagram</a>.</video><p class="video-note">Fictional AI creator. Captions included. Sound on when you’re ready.</p></div></section><section class="wrap closing"><p class="eyebrow" style="justify-content:center">Keep it going</p><h2>{h['tagline']}</h2><p>Find {h['name'].split()[0]} on Instagram.</p><a class="button" href="{insta}">@{h['handle']} <span aria-hidden="true">↗</span></a></section></main>{footer(h['name'])}<div class="sticky"><a class="button" href="{insta}">Follow {h['name'].split()[0]} on Instagram ↗</a></div>{dialog()}</body></html>'''
    (ROOT / (h['slug'] + '.html')).write_text(head(h['name']+' | '+h['niche'],h['intro']+' Fictional AI creator.',h['slug'],h['asset']+'-profile.jpg') + body)
    srt = (ROOT/'assets/creators'/(h['asset']+'.srt')).read_text()
    import re
    vtt = re.sub(r'(\d\d:\d\d:\d\d),(\d\d\d)',r'\1.\2',srt)
    (ROOT/'assets/creators'/ (h['asset']+'.vtt')).write_text('WEBVTT\n\n'+vtt)

policies = {
 'privacy': ('Privacy Policy', '<p>This policy covers the June Rowan, Nora Vela and Elena Brooks creator pages operated by Web By Elie.</p><h2>Browsing these pages</h2><p>These pages have no sign-in, contact forms, payments, advertising trackers or analytics scripts. Videos and images are served from this website through Cloudflare. Hosting providers process connection information, such as IP addresses and request logs, to deliver and protect the site under their own policies.</p><h2>Display preferences</h2><p>If you change the display settings, your theme and glass preferences are stored locally in your browser. They are not sent to us. Clear your browser’s site data to remove them.</p><h2>External services and email</h2><p>Instagram links open Instagram, which handles your activity under Meta’s policies. Email sent to us is handled by our email providers and used to respond to your request. We do not load Instagram embeds or third-party fonts on these creator pages.</p><p>For privacy questions or deletion requests, email <a href="mailto:hello@web-by-elie.com">hello@web-by-elie.com</a>.</p>'),
 'terms': ('Terms of Service', '<p>These creator pages are operated by Web By Elie. June Rowan, Nora Vela and Elena Brooks are fictional AI characters. Their portraits, voices and videos are generated or edited with AI. They are not real people and do not have personal experience or professional credentials.</p><h2>Content</h2><p>The videos share general everyday ideas and business experiments. They are not personalized medical, financial or relationship counseling. Nora’s first video uses explicitly made-up numbers; it is not a statement of earnings or a promise of profit.</p><h2>External links</h2><p>Instagram and other external services have their own terms. These pages do not sell products, accept payments or create subscriptions. Any future offer will state its own terms.</p><h2>Contact</h2><p>For questions about this content, email <a href="mailto:hello@web-by-elie.com">hello@web-by-elie.com</a>.</p>'),
 'data-deletion': ('Data Deletion Instructions', '<p>The June Rowan, Nora Vela and Elena Brooks creator pages do not create visitor accounts or store submitted form, payment or analytics data.</p><h2>Browser preferences</h2><p>Display preferences are saved only in your browser. Remove them by clearing site data for web-by-elie.com.</p><h2>Information sent by email</h2><p>To request deletion or correction of information you sent us, email <a href="mailto:hello@web-by-elie.com">hello@web-by-elie.com</a>. Include the email address you used, an approximate message date and what you want removed. Do not send a password or identity document.</p><h2>Platform data</h2><p>Data held by Instagram or your email provider must be managed through that service’s own account and privacy tools. Hosting security logs are handled by the hosting provider under its retention policies.</p>')
}
for slug, (title, content) in policies.items():
    path = 'creators.'+slug
    links = ' · '.join(f'<a href="{h["slug"]}">{h["name"]}</a>' for h in HOSTS)
    body = f'<body><header class="wrap bar"><a class="brand" href="june.rowan">Creator pages</a>{settings()}</header><main class="wrap policy"><p class="eyebrow">Web By Elie · Updated October 16, 2026</p><h1>{title}</h1>{content}<p>{links}</p></main>{footer("Creator pages")}{dialog()}</body></html>'
    (ROOT/(path+'.html')).write_text(head(title+' | Creator pages', title+' for the fictional AI creator pages operated by Web By Elie.',path)+body)
print('Generated three character pages and three scoped policy pages.')
